from __future__ import annotations

from collections import defaultdict
from statistics import median

from ..models import AuditIssue, AuditSummary, FileProfile, RunProfile


CHECKS = [
    "missing_values",
    "infinities",
    "empty_signals",
    "inconsistent_channel_count",
    "inconsistent_schema",
    "sequence_length_distribution",
    "timestamp_monotonicity",
    "sampling_rate_variation",
    "constant_or_near_constant_channels",
    "exact_duplicate_files_or_arrays",
    "duplicate_ids",
]


def audit_profile_inputs(files: list[FileProfile], runs: list[RunProfile]) -> AuditSummary:
    issues: list[AuditIssue] = []

    for file in files:
        for variable in file.variables:
            if variable.nan_count:
                issues.append(AuditIssue("error", "missing_values", f"{variable.nan_count} NaN values in {variable.name}", [file.source_run_id], [file.relative_path]))
            if variable.inf_count:
                issues.append(AuditIssue("error", "infinities", f"{variable.inf_count} infinite values in {variable.name}", [file.source_run_id], [file.relative_path]))
            if variable.size == 0:
                issues.append(AuditIssue("error", "empty_signals", f"Empty variable {variable.name}", [file.source_run_id], [file.relative_path]))

    schemas: dict[str, dict[str, tuple[tuple[int, ...], str]]] = defaultdict(dict)
    channels: dict[str, dict[str, int]] = defaultdict(dict)
    for file in files:
        for variable in file.variables:
            shape = tuple(variable.shape)
            if variable.ndim == 2 and len(shape) == 2 and shape[1] > shape[0]:
                schema_shape = (shape[0], -1)  # sample count is intentionally variable
            elif variable.ndim == 2 and len(shape) == 2 and shape[1] == 1:
                schema_shape = (-1, 1)  # variable-length column vector
            else:
                schema_shape = shape
            schemas[file.source_run_id][variable.name] = (schema_shape, variable.dtype)
            if variable.ndim == 2 and len(variable.shape) == 2 and variable.shape[1] > variable.shape[0]:
                channels[variable.name][file.source_run_id] = variable.shape[0]

    all_variables = sorted({name for schema in schemas.values() for name in schema})
    for name in all_variables:
        observed = {run_id: schema.get(name) for run_id, schema in schemas.items()}
        if len(set(observed.values())) > 1:
            issues.append(AuditIssue("warning", "inconsistent_schema", f"Schema differs across runs for {name}", sorted(observed), details={k: v for k, v in observed.items()}))
        counts = channels.get(name, {})
        if len(set(counts.values())) > 1:
            issues.append(AuditIssue("warning", "inconsistent_channel_count", f"Row count differs across runs for {name}", sorted(counts), details=counts))

    lengths = {run.source_run_id: run.sequence_length for run in runs}
    valid_lengths = [value for value in lengths.values() if value is not None]
    if valid_lengths and len(set(valid_lengths)) > 1:
        issues.append(AuditIssue("warning", "sequence_length_distribution", "Sequence lengths differ across runs", sorted(lengths), details={"by_run": lengths, "min": min(valid_lengths), "median": median(valid_lengths), "max": max(valid_lengths)}))
    for run in runs:
        if run.timestamps_monotonic is False:
            issues.append(AuditIssue("error", "timestamp_monotonicity", "Timestamp axis is not strictly increasing", [run.source_run_id]))

    rates = {run.source_run_id: run.sampling_rate_hz for run in runs if run.sampling_rate_hz is not None}
    if rates and max(rates.values()) - min(rates.values()) > max(rates.values()) * 1e-6:
        issues.append(AuditIssue("warning", "sampling_rate_variation", "Sampling rate differs across runs", sorted(rates), details=rates))

    for file in files:
        for variable in file.variables:
            # Row zero is commonly time; the profiler reports it, but the dataset-level
            # signal interpretation decides whether to exclude it downstream.
            affected = [stat.index for stat in variable.channel_stats if stat.constant or stat.near_constant]
            if affected:
                issues.append(AuditIssue("info", "constant_or_near_constant_channels", f"{variable.name} has constant or near-constant rows", [file.source_run_id], [file.relative_path], {"row_indices": affected}))

    for attribute, label in (("sha256", "files"),):
        groups: dict[str, list[str]] = defaultdict(list)
        for file in files:
            groups[getattr(file, attribute)].append(file.relative_path)
        for paths in groups.values():
            if len(paths) > 1:
                issues.append(AuditIssue("warning", "exact_duplicate_files_or_arrays", f"Exact duplicate source {label}", affected_files=sorted(paths)))
    content_groups: dict[str, list[str]] = defaultdict(list)
    for file in files:
        for variable in file.variables:
            if variable.content_sha256:
                content_groups[variable.content_sha256].append(f"{file.relative_path}:{variable.name}")
    for members in content_groups.values():
        if len(members) > 1:
            issues.append(AuditIssue("warning", "exact_duplicate_files_or_arrays", "Exact duplicate variable payloads", affected_files=sorted(members)))
    run_payloads: dict[str, list[str]] = defaultdict(list)
    for run in runs:
        payload_hashes = sorted(
            variable.content_sha256
            for file in files
            if file.source_run_id == run.source_run_id
            for variable in file.variables
            if variable.content_sha256 and variable.name != "rt_tout"
        )
        signature = "|".join(payload_hashes)
        if signature:
            run_payloads[signature].append(run.source_run_id)
    for run_ids in run_payloads.values():
        if len(run_ids) > 1:
            issues.append(AuditIssue("error", "exact_duplicate_files_or_arrays", "Exact duplicate experimental sequences", affected_runs=sorted(run_ids)))

    for attr in ("internal_id", "source_run_id", "original_sequence_id"):
        groups: dict[str, list[str]] = defaultdict(list)
        for run in runs:
            groups[getattr(run, attr)].append(run.source_directory)
        duplicate_values = {key: paths for key, paths in groups.items() if len(paths) > 1}
        if duplicate_values:
            issues.append(AuditIssue("error", "duplicate_ids", f"Duplicate {attr} values", details=duplicate_values))

    return AuditSummary(CHECKS.copy(), issues)

from __future__ import annotations

from collections import Counter, defaultdict
from pathlib import Path
import hashlib
from typing import Any

import numpy as np

from .audit import audit_profile_inputs
from .datasets import KukaCollisionHints
from .inspection import inspect_mat_file
from .io.matlab import load_matlab
from .models import DatasetProfile, RunProfile


def discover_runs(root: str | Path) -> list[Path]:
    source = Path(root).resolve()
    if list(source.glob("*.mat")):
        return [source]
    return sorted(
        directory
        for directory in source.iterdir()
        if directory.is_dir() and any(directory.glob("*.mat"))
    )


def _stable_run_id(dataset_id: str, source_run_id: str) -> str:
    suffix = hashlib.sha256(f"{dataset_id}\0{source_run_id}".encode()).hexdigest()[:12]
    return f"{dataset_id}:{source_run_id}:{suffix}"


def _find_time_axis(run_dir: Path) -> tuple[np.ndarray | None, str | None]:
    candidates = [(run_dir / "JsmoExp.mat", "rt_tout")]
    candidates.extend((path, "") for path in sorted(run_dir.glob("*.mat")))
    for path, preferred in candidates:
        if not path.exists():
            continue
        for name, value in load_matlab(path).variables.items():
            array = np.asarray(value)
            if preferred and name != preferred:
                continue
            flat = array.reshape(-1)
            if flat.size >= 2 and np.issubdtype(flat.dtype, np.number):
                differences = np.diff(flat)
                if np.all(np.isfinite(flat)) and np.all(differences > 0):
                    return flat, f"{path.name}:{name}"
        if preferred:
            continue
    return None, None


def _run_profile(dataset_id: str, root: Path, run_dir: Path, hints: Any | None) -> RunProfile:
    source_run_id = run_dir.relative_to(root).as_posix() if run_dir != root else run_dir.name
    time_axis, time_source = _find_time_axis(run_dir)
    rate = None
    monotonic = None
    if time_axis is not None:
        differences = np.diff(time_axis)
        monotonic = bool(np.all(differences > 0))
        if monotonic:
            rate = float(1.0 / np.median(differences))
            if np.isclose(rate, round(rate), rtol=1e-9, atol=1e-9):
                rate = float(round(rate))
    metadata = hints.parse_run_metadata(run_dir) if hints else {}
    if time_source:
        metadata["time_axis_source"] = time_source
    events = hints.events(run_dir, time_axis) if hints else []
    if events and metadata.get("collision_times") is not None:
        metadata["event_count_matches_readme"] = len(events) == len(metadata["collision_times"])
        start = metadata.get("start_time")
        if start and len(events) == len(metadata["collision_times"]):
            def seconds(value: str) -> int:
                hours, minutes, secs = map(int, value.split(":"))
                return hours * 3600 + minutes * 60 + secs

            start_seconds = seconds(start)
            offsets = [(seconds(value) - start_seconds) % 86400 for value in metadata["collision_times"]]
            errors = [abs(offset - event.inferred_time_seconds) for offset, event in zip(offsets, events) if event.inferred_time_seconds is not None]
            metadata["event_time_alignment_max_abs_seconds"] = max(errors) if errors else None
    return RunProfile(
        internal_id=_stable_run_id(dataset_id, source_run_id),
        dataset_id=dataset_id,
        source_run_id=source_run_id,
        original_sequence_id=run_dir.name,
        source_directory=source_run_id,
        source_files=sorted(path.relative_to(root).as_posix() for path in run_dir.iterdir() if path.is_file()),
        sequence_length=int(time_axis.size) if time_axis is not None else None,
        channel_counts={},
        sampling_rate_hz=rate,
        time_start=float(time_axis[0]) if time_axis is not None else None,
        time_end=float(time_axis[-1]) if time_axis is not None else None,
        timestamps_monotonic=monotonic,
        metadata=metadata,
        events=events,
    )


def _signal_summary(files: list[Any], hints: Any | None) -> list[dict[str, Any]]:
    observations: dict[str, list[tuple[str, Any]]] = defaultdict(list)
    for file in files:
        for variable in file.variables:
            observations[variable.name].append((file.source_run_id, variable))
    summaries: list[dict[str, Any]] = []
    names = hints.signal_names if hints else {}
    for name, items in sorted(observations.items()):
        shapes = sorted({tuple(variable.shape) for _, variable in items})
        dtypes = sorted({variable.dtype for _, variable in items})
        matrix = all(variable.ndim == 2 for _, variable in items)
        has_embedded_time = matrix and all(
            variable.shape[0] > 1 and variable.shape[1] > variable.shape[0]
            for _, variable in items
        ) and name not in {"JK_moments"}
        summaries.append(
            {
                "observed_name": name,
                "observed_shapes": [list(shape) for shape in shapes],
                "observed_dtypes": dtypes,
                "files_count": len(items),
                "has_embedded_time_row": has_embedded_time,
                "data_channel_count": sorted({v.shape[0] - 1 for _, v in items}) if has_embedded_time else None,
                "inferred_semantic_name": {
                    "value": names.get(name, "unknown"),
                    "confidence": 0.98 if name in names else 0.0,
                    "evidence": ["dataset-specific KUKA hint mapping"] if name in names else [],
                },
            }
        )
    return summaries


def profile_dataset(
    source: str | Path,
    dataset_id: str,
    *,
    hints: Any | None = None,
) -> DatasetProfile:
    root = Path(source).resolve()
    if not root.is_dir():
        raise ValueError(f"Dataset source is not a directory: {root}")
    run_dirs = discover_runs(root)
    if not run_dirs:
        raise ValueError(f"No directories containing MAT files found under {root}")

    runs = [_run_profile(dataset_id, root, run_dir, hints) for run_dir in run_dirs]
    by_source_id = {run.source_run_id: run for run in runs}
    files = []
    for run_dir in run_dirs:
        source_run_id = run_dir.relative_to(root).as_posix() if run_dir != root else run_dir.name
        for path in sorted(run_dir.glob("*.mat")):
            profile = inspect_mat_file(path, root, source_run_id)
            files.append(profile)
            for variable in profile.variables:
                likely_time_row = (
                    variable.ndim == 2
                    and len(variable.shape) == 2
                    and variable.shape[0] > 1
                    and variable.shape[1] > variable.shape[0]
                    and variable.name != "JK_moments"
                )
                if likely_time_row:
                    by_source_id[source_run_id].channel_counts[variable.name] = variable.shape[0] - 1

    format_counts = Counter(file.format for file in files)
    variable_schema: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for file in files:
        for variable in file.variables:
            observation = {"shape": variable.shape, "dtype": variable.dtype, "ndim": variable.ndim}
            if observation not in variable_schema[variable.name]:
                variable_schema[variable.name].append(observation)
    audit = audit_profile_inputs(files, runs)
    semantics = hints.semantic_claims() if hints else []
    unknowns = hints.unknowns() if hints else ["Signal semantics and record boundaries have not been identified."]
    return DatasetProfile(
        schema_version="1.0.0",
        dataset_id=dataset_id,
        source={
            "path": str(root),
            "scope": "Part I Batch 01" if isinstance(hints, KukaCollisionHints) else "user-provided directory",
            "raw_data_copied": False,
        },
        discovery={
            "run_directories": len(run_dirs),
            "mat_files": len(files),
            "all_files": sum(len(run.source_files) for run in runs),
            "matlab_formats": dict(sorted(format_counts.items())),
            "compression_layout": "already extracted; no archive found inside source directory",
        },
        files=files,
        runs=runs,
        observed_structure={
            "record_boundary": "directory containing MAT files",
            "variable_schema": dict(sorted(variable_schema.items())),
            "sequence_lengths": [run.sequence_length for run in runs],
            "sampling_rates_hz": [run.sampling_rate_hz for run in runs],
        },
        signals=_signal_summary(files, hints),
        entities=[
            {
                "entity_type": "experimental_run",
                "count": len(runs),
                "identifier_fields": ["dataset_id", "source_run_id", "original_sequence_id", "internal_id"],
                "future_window_provenance_fields": ["source_run_id", "window_start", "window_end"],
            }
        ],
        metadata={
            "run_metadata_sources": sorted({run.metadata.get("metadata_source") for run in runs if run.metadata.get("metadata_source")}),
            "dataset_specific_hints": type(hints).__name__ if hints else None,
        },
        quality=audit,
        inferred_semantics=semantics,
        unknowns=unknowns,
    )

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterator
import hashlib

import numpy as np


class MatlabLoadError(RuntimeError):
    pass


@dataclass
class LoadedMatlab:
    variables: dict[str, Any]
    loader: str
    format: str


def sha256_file(path: Path, chunk_size: int = 1024 * 1024) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        while chunk := stream.read(chunk_size):
            digest.update(chunk)
    return digest.hexdigest()


def matlab_format(path: Path) -> str:
    with path.open("rb") as stream:
        header = stream.read(128)
    if header.startswith(b"MATLAB 7.3 MAT-file") or header.startswith(b"\x89HDF"):
        return "matlab-v7.3-hdf5"
    if header.startswith(b"MATLAB"):
        return "matlab-v5"
    return "matlab-v4-or-earlier"


def load_matlab(path: str | Path) -> LoadedMatlab:
    source = Path(path)
    detected = matlab_format(source)
    if detected != "matlab-v7.3-hdf5":
        try:
            from scipy.io import loadmat

            values = loadmat(source, struct_as_record=False, squeeze_me=False)
            return LoadedMatlab(
                variables={k: v for k, v in values.items() if not k.startswith("__")},
                loader="scipy.io.loadmat",
                format=detected,
            )
        except (NotImplementedError, ValueError) as error:
            if "7.3" not in str(error) and detected != "matlab-v7.3-hdf5":
                raise MatlabLoadError(f"Could not load {source}: {error}") from error

    try:
        import h5py
    except ImportError as error:
        raise MatlabLoadError(
            f"{source} is an HDF5/MATLAB v7.3 file; install the 'hdf5' extra"
        ) from error

    def materialize(node: Any, handle: Any) -> Any:
        if isinstance(node, h5py.Dataset):
            array = np.asarray(node)
            if h5py.check_dtype(ref=node.dtype) is not None:
                resolved = np.empty(array.shape, dtype=object)
                for index, reference in np.ndenumerate(array):
                    resolved[index] = materialize(handle[reference], handle) if reference else None
                return resolved
            # MATLAB stores array dimensions in the reverse order in v7.3 files.
            return array.transpose(tuple(reversed(range(array.ndim)))) if array.ndim > 1 else array
        return {name: materialize(child, handle) for name, child in node.items()}

    try:
        with h5py.File(source, "r") as handle:
            values = {
                name: materialize(node, handle)
                for name, node in handle.items()
                if name != "#refs#"
            }
    except OSError as error:
        raise MatlabLoadError(f"Could not load {source}: {error}") from error
    return LoadedMatlab(values, "h5py", "matlab-v7.3-hdf5")


def iter_arrays(value: Any, prefix: str = "") -> Iterator[tuple[str, np.ndarray]]:
    if isinstance(value, np.ndarray):
        if value.dtype.names:
            for field_name in value.dtype.names:
                yield from iter_arrays(value[field_name], f"{prefix}.{field_name}")
        elif value.dtype == object:
            for index, item in np.ndenumerate(value):
                suffix = ",".join(map(str, index))
                yield from iter_arrays(item, f"{prefix}[{suffix}]")
        else:
            yield prefix, value
    elif isinstance(value, dict):
        for name, item in value.items():
            yield from iter_arrays(item, f"{prefix}.{name}" if prefix else name)
    elif hasattr(value, "_fieldnames"):
        for name in value._fieldnames:
            yield from iter_arrays(getattr(value, name), f"{prefix}.{name}")


def describe_nested(value: Any, depth: int = 0, max_depth: int = 5) -> Any:
    if depth >= max_depth:
        return {"type": type(value).__name__, "truncated": True}
    if isinstance(value, dict):
        return {
            "type": "dict",
            "fields": {
                str(k): describe_nested(v, depth + 1, max_depth)
                for k, v in value.items()
            },
        }
    if hasattr(value, "_fieldnames"):
        return {
            "type": "matlab_struct",
            "fields": {
                name: describe_nested(getattr(value, name), depth + 1, max_depth)
                for name in value._fieldnames
            },
        }
    if isinstance(value, np.ndarray):
        result: dict[str, Any] = {
            "type": "ndarray",
            "shape": list(value.shape),
            "dtype": str(value.dtype),
        }
        if value.dtype.names:
            result["fields"] = list(value.dtype.names)
        elif value.dtype == object and value.size <= 20:
            result["items"] = [
                describe_nested(item, depth + 1, max_depth) for item in value.flat
            ]
        return result
    return {"type": type(value).__name__, "value": repr(value)[:200]}

